using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using Modeller.Core;
namespace Modeller.Application;

public sealed class Traceability(SnapshotRepository repository,ModellingIdentity actor,StandardsGateway engine)
{
    public const string Path="requirements/traceability.json";
    private static readonly string[] Models=["archetype","template","template_constraint","terminology_binding"];
    private static string S(JsonObject o,string k,string fallback="")=>KnowledgeCorpus.Text(o,k,fallback);
    private static JsonObject Graph(JsonObject graph){
        Data.Keys(graph,"schema","nodes","edges");if(graph["schema"]?.GetValue<int>()!=1||graph["nodes"] is not JsonArray nodes||graph["edges"] is not JsonArray edges||nodes.Count>500||edges.Count>2000||graph.ToJsonString().Length>1048576)throw new ProcessingException("INVALID_TRACEABILITY_SCHEMA");
        var indexed=new Dictionary<string,JsonObject>(StringComparer.Ordinal);
        foreach(var item in nodes){var node=item as JsonObject??throw new ProcessingException("INVALID_TRACEABILITY_NODE");var id=S(node,"id");var type=S(node,"type");if(!Regex.IsMatch(id,"^[A-Za-z][A-Za-z0-9_.:-]{0,99}$")||!indexed.TryAdd(id,node)||!new[]{"requirement","decision","archetype","template","template_constraint","terminology_binding","validation_evidence","review"}.Contains(type)||string.IsNullOrWhiteSpace(S(node,"title"))||S(node,"title").Length>300||string.IsNullOrWhiteSpace(S(node,"description"))||S(node,"description").Length>8000||node["provenance"] is not JsonArray {Count:>0 and <=20} provenance||provenance.Any(p=>p is not JsonValue||string.IsNullOrWhiteSpace(p.GetValue<string>())||p.GetValue<string>().Length>2000))throw new ProcessingException("INVALID_TRACEABILITY_NODE");
            if(type=="requirement"&&(!new[]{"must","should","could"}.Contains(S(node,"priority"))||!new[]{"ACTIVE","EXCLUDED"}.Contains(S(node,"status"))||S(node,"status")=="EXCLUDED"&&string.IsNullOrWhiteSpace(S(node,"exclusion_reason"))))throw new ProcessingException("INVALID_TRACEABILITY_REQUIREMENT");
            if(type=="decision"&&(string.IsNullOrWhiteSpace(S(node,"rationale"))||!new[]{"OPEN","PROPOSED","RECORDED","SUPERSEDED"}.Contains(S(node,"status"))))throw new ProcessingException("INVALID_TRACEABILITY_DECISION");
            if(Models.Contains(type)){
                var a=node["artifact"] as JsonObject??throw new ProcessingException("TRACEABILITY_ARTIFACT_REQUIRED");Data.Keys(a,"path","revision","sha256","anchor");SnapshotRepository.ArtifactPath(Data.Required(a,"path"));if(string.IsNullOrWhiteSpace(S(a,"revision"))||!Regex.IsMatch(S(a,"sha256"),"^[a-f0-9]{64}$"))throw new ProcessingException("INVALID_TRACEABILITY_ARTIFACT");var prefix=type=="archetype"?"archetypes/":type=="terminology_binding"?"terminology/":"templates/";if(!S(a,"path").StartsWith(prefix,StringComparison.Ordinal))throw new ProcessingException("INVALID_TRACEABILITY_ARTIFACT_PATH");
                if(a["anchor"] is JsonObject anchor){Data.Keys(anchor,"kind","value");if(!new[]{"xml_location","openehr_path","json_pointer"}.Contains(S(anchor,"kind"))||!S(anchor,"value").StartsWith('/')||S(anchor,"value").Length>2000)throw new ProcessingException("INVALID_TRACEABILITY_ANCHOR");}else if(type=="template_constraint")throw new ProcessingException("TRACEABILITY_CONSTRAINT_ANCHOR_REQUIRED");
            }else if(type is "validation_evidence" or "review"){var e=node["event"] as JsonObject??throw new ProcessingException("TRACEABILITY_EVENT_REQUIRED");Data.Keys(e,"subject","sequence","hash");if(!Regex.IsMatch(S(e,"subject"),"^[a-f0-9]{64}$")||!Regex.IsMatch(S(e,"hash"),"^[a-f0-9]{64}$")||e["sequence"]?.GetValue<int>() is not (>=1 and <=256))throw new ProcessingException("INVALID_TRACEABILITY_EVENT");}
        }
        var seen=new HashSet<string>(StringComparer.Ordinal);var degree=indexed.Keys.ToDictionary(k=>k,_=>0,StringComparer.Ordinal);var adjacency=indexed.Keys.ToDictionary(k=>k,_=>new List<string>(),StringComparer.Ordinal);
        foreach(var item in edges){var e=item as JsonObject??throw new ProcessingException("INVALID_TRACEABILITY_EDGE");Data.Keys(e,"from","to","relation","rationale","coverage");var from=S(e,"from");var to=S(e,"to");var relation=S(e,"relation");if(from==to||!indexed.TryGetValue(from,out var f)||!indexed.TryGetValue(to,out var t)||string.IsNullOrWhiteSpace(S(e,"rationale"))||S(e,"rationale").Length>4000||!seen.Add(from+"|"+relation+"|"+to))throw new ProcessingException("BROKEN_TRACEABILITY_EDGE");var ft=S(f,"type");var tt=S(t,"type");var valid=relation switch{"motivates"=>ft=="requirement"&&tt=="decision","justifies"=>ft=="decision"&&Models.Contains(tt),"satisfied_by"=>ft=="requirement"&&Models.Contains(tt)&&new[]{"full","partial"}.Contains(S(e,"coverage"))&&S(f,"status")!="EXCLUDED","used_by"=>ft=="archetype"&&tt=="template","constrains"=>ft=="template"&&tt=="template_constraint","bound_by"=>new[]{"archetype","template","template_constraint"}.Contains(ft)&&tt=="terminology_binding","validated_by"=>Models.Contains(ft)&&tt=="validation_evidence","reviewed_by"=>(Models.Contains(ft)||ft=="validation_evidence")&&tt=="review","supersedes"=>ft=="decision"&&tt=="decision",_=>false};if(!valid)throw new ProcessingException("INVALID_TRACEABILITY_RELATION");degree[to]++;adjacency[from].Add(to);}
        var queue=new Queue<string>(degree.Where(p=>p.Value==0).Select(p=>p.Key));var count=0;while(queue.TryDequeue(out var id)){count++;foreach(var to in adjacency[id])if(--degree[to]==0)queue.Enqueue(to);}if(count!=nodes.Count)throw new ProcessingException("TRACEABILITY_CYCLE");return(JsonObject)graph.DeepClone();
    }
    public async Task<JsonObject> Execute(string tool,JsonObject args,CancellationToken cancellation){
        var project=Data.Required(args,"project");actor.Read(project);JsonObject graph,artifact;
        if(tool=="model_traceability_save"){
            actor.Write(project);graph=Graph(args["graph"] as JsonObject??throw new ProcessingException("TRACEABILITY_GRAPH_REQUIRED"));var resolved=await Resolve(project,graph,cancellation);if(resolved.Values.OfType<JsonObject>().Any(e=>S(e,"status") is "INVALID" or "UNAVAILABLE"))throw new ProcessingException("INVALID_TRACEABILITY_REFERENCES");artifact=repository.Save(project,Path,graph.ToJsonString(),new JsonObject{["kind"]="requirements_traceability",["schema"]=1},args["expectedRevision"]?.GetValue<string>());
        }else{artifact=repository.Artifact(project,Path,args["revision"]?.GetValue<string>());graph=Graph(JsonNode.Parse(S(artifact,"content")) as JsonObject??throw new ProcessingException("INVALID_TRACEABILITY_DOCUMENT"));}
        var evidence=await Resolve(project,graph,cancellation);var nodes=((JsonArray)graph["nodes"]!).OfType<JsonObject>().ToDictionary(n=>S(n,"id"),StringComparer.Ordinal);var edges=((JsonArray)graph["edges"]!).OfType<JsonObject>().ToArray();var coverage=new JsonArray();foreach(var n in nodes.Values.Where(n=>S(n,"type")=="requirement")){
            var links=edges.Where(e=>S(e,"from")==S(n,"id")&&S(e,"relation")=="satisfied_by").ToArray();var status=S(n,"status")=="EXCLUDED"?"EXCLUDED":links.Length==0?"UNRESOLVED":links.Any(e=>S(e,"coverage")=="partial")?"DECLARED_PARTIAL":"DECLARED_FULL";coverage.Add(new JsonObject{["requirement"]=S(n,"id"),["status"]=status,["references_current"]=links.Length>0&&links.All(e=>evidence[S(e,"to")]?["status"]?.GetValue<string>()=="VERIFIED"),["links"]=new JsonArray(links.Select(e=>e.DeepClone()).ToArray())});
        }
        var report=new JsonObject{["artifact"]=TemplateAuthoring.Reference(artifact),["graph"]=graph,["resolved"]=System.Text.Json.JsonSerializer.SerializeToNode(evidence),["coverage"]=coverage,["clinical_approval"]=false,["basis"]="Explicit versioned assertions and checked references; no inferred clinical satisfaction."};
        if(tool is "model_traceability_explain" or "model_traceability_requirement"){
            var start=Data.Required(args,tool=="model_traceability_explain"?"node":"requirement");if(!nodes.ContainsKey(start)||tool=="model_traceability_requirement"&&S(nodes[start],"type")!="requirement")throw new ProcessingException("TRACEABILITY_NODE_NOT_FOUND");var selected=new HashSet<string>(StringComparer.Ordinal){start};var todo=new Queue<string>();todo.Enqueue(start);while(todo.TryDequeue(out var id)){foreach(var e in edges){var next=tool=="model_traceability_explain"?S(e,"to")==id?S(e,"from"):"":S(e,"from")==id?S(e,"to"):"";if(next!=""&&selected.Add(next))todo.Enqueue(next);}}
            report["selected_nodes"]=new JsonArray(nodes.Where(p=>selected.Contains(p.Key)).Select(p=>(JsonNode)p.Value.DeepClone()).ToArray());report["query"]=new JsonObject{["kind"]=tool=="model_traceability_explain"?"why_element":"requirement_coverage",["node"]=start};
        }return report;
    }
    private async Task<Dictionary<string,JsonNode?>> Resolve(string project,JsonObject graph,CancellationToken cancellation){
        var result=new Dictionary<string,JsonNode?>(StringComparer.Ordinal);var bytes=0;var sources=new Dictionary<string,JsonObject>(StringComparer.Ordinal);var latest=new Dictionary<string,JsonObject>(StringComparer.Ordinal);var eventSources=new Dictionary<string,JsonObject?>(StringComparer.Ordinal);var eventDigests=new Dictionary<string,string>(StringComparer.Ordinal);using var ledger=new AuditLedger();
        foreach(var n in ((JsonArray)graph["nodes"]!).OfType<JsonObject>()){
            var status="DECLARED";var detail="Versioned modeller assertion.";
            try{
                if(n["artifact"] is JsonObject reference){var sourceKey=S(reference,"path")+"\n"+S(reference,"revision");if(!sources.TryGetValue(sourceKey,out var source)){source=repository.Artifact(project,S(reference,"path"),S(reference,"revision"));bytes+=System.Text.Encoding.UTF8.GetByteCount(S(source,"content"));if(bytes>16777216)throw new ProcessingException("TRACEABILITY_CONTEXT_LIMIT");sources[sourceKey]=source;}if(!latest.TryGetValue(S(reference,"path"),out var current)){current=repository.Artifact(project,S(reference,"path"));latest[S(reference,"path")]=current;}if(S(source,"sha256")!=S(reference,"sha256")||Data.Hash(S(source,"content"))!=S(reference,"sha256"))throw new ProcessingException("TRACEABILITY_HASH_MISMATCH");status=S(current,"revision")==S(reference,"revision")?"VERIFIED":"STALE";
                    if(reference["anchor"] is JsonObject anchor){var kind=S(anchor,"kind");var path=S(anchor,"value");var content=S(source,"content");bool exists;
                        if(kind=="json_pointer"){JsonNode? value=Data.ParseStrict(System.Text.Encoding.UTF8.GetBytes(content));exists=true;foreach(var part in path.Split('/').Skip(1)){var key=part.Replace("~1","/",StringComparison.Ordinal).Replace("~0","~",StringComparison.Ordinal);if(value is JsonObject obj&&obj.TryGetPropertyValue(key,out var child))value=child;else if(value is JsonArray arr&&Regex.IsMatch(key,"^(0|[1-9][0-9]*)$")&&int.TryParse(key,out var index)&&index>=0&&index<arr.Count)value=arr[index];else{exists=false;break;}}}
                        else if(kind=="xml_location"){var doc=Imports.Xml(content);IEnumerable<XElement> currentElements=doc.Root is null?[]:[doc.Root];var first=true;foreach(var segment in path.Split('/').Skip(1)){var m=Regex.Match(segment,"^([A-Za-z_][A-Za-z0-9_.-]*)(?:\\[([1-9][0-9]*)\\])?$");if(!m.Success)throw new ProcessingException("TRACEABILITY_ANCHOR_INVALID");var name=m.Groups[1].Value;var candidates=first?currentElements.Where(e=>e.Name.LocalName==name):currentElements.SelectMany(e=>e.Elements().Where(c=>c.Name.LocalName==name));var list=candidates.ToArray();currentElements=m.Groups[2].Success?list.Skip(int.Parse(m.Groups[2].Value,System.Globalization.CultureInfo.InvariantCulture)-1).Take(1):list;first=false;}exists=currentElements.Take(2).Count()==1;}
                        else{var report=await engine.Native(content.TrimStart().StartsWith('<')?"inspect/opt":"inspect/archetype",content,null,cancellation);exists=(report["inspection"]?["paths"] as JsonArray??[]).OfType<JsonObject>().Any(p=>S(p,"path")==path);}
                        if(!exists)throw new ProcessingException("TRACEABILITY_ANCHOR_NOT_FOUND");
                    }
                }else if(n["event"] is JsonObject pin){var events=ledger.Events(actor.Tenant,S(pin,"subject"));var seq=pin["sequence"]!.GetValue<int>();var e=seq<=events.Count?events[seq-1] as JsonObject:null;if(e is null||S(e,"hash")!=S(pin,"hash")||S(e,"project")!=project)throw new ProcessingException("TRACEABILITY_EVENT_INVALID");if(S(n,"type")=="validation_evidence"&&S(e,"type")!="VALIDATION")throw new ProcessingException("TRACEABILITY_EVENT_INVALID");if(S(n,"type")=="review"&&S(e,"type")!="TRANSITION")throw new ProcessingException("TRACEABILITY_EVENT_INVALID");eventSources[S(n,"id")]=events[0]?["source"] as JsonObject;eventDigests[S(n,"id")]=S(e,"validation_digest");status="VERIFIED";detail="Protected ledger event and exact hash verified; this does not certify graph assertions.";}
            }catch(ProcessingException e){status=e.Code is "ENGINE_NOT_CONFIGURED" or "ENGINE_UNAVAILABLE"?"UNAVAILABLE":"INVALID";detail=e.Code;}
            result[S(n,"id")]=new JsonObject{["status"]=status,["scope"]=detail};
        }
        var nodeIndex=((JsonArray)graph["nodes"]!).OfType<JsonObject>().ToDictionary(n=>S(n,"id"),StringComparer.Ordinal);
        foreach(var edge in ((JsonArray)graph["edges"]!).OfType<JsonObject>().Where(e=>S(e,"relation") is "validated_by" or "reviewed_by")){
            var from=S(edge,"from");var to=S(edge,"to");var expected=nodeIndex[from]["artifact"] as JsonObject??eventSources.GetValueOrDefault(from);var actual=eventSources.GetValueOrDefault(to);
            var same=expected is not null&&actual is not null&&new[]{"path","revision","sha256"}.All(k=>S(expected,k)==S(actual,k));
            if(S(edge,"relation")=="reviewed_by"&&S(nodeIndex[from],"type")=="validation_evidence")same= same&&eventDigests.GetValueOrDefault(from) is {Length:>0} digest&&digest==eventDigests.GetValueOrDefault(to);
            if(!same)result[to]=new JsonObject{["status"]="INVALID",["scope"]="TRACEABILITY_EVIDENCE_SOURCE_OR_VALIDATION_MISMATCH"};
        }
        return result;
    }
    public static JsonObject Coverage(JsonObject args,JsonArray? artifacts=null){var requirements=args["requirements"] as JsonArray??[];var links=(args["links"] as JsonArray??[]).OfType<JsonObject>().ToArray();var paths=(artifacts??[]).OfType<JsonObject>().Select(a=>S(a,"path")).ToHashSet(StringComparer.Ordinal);var rows=new JsonArray();var counts=new JsonObject{["fully_modelled"]=0,["partially_modelled"]=0,["unresolved"]=0,["intentionally_excluded"]=0};var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var requirement in requirements.OfType<JsonObject>()){var id=Data.Required(requirement,"id");if(!ids.Add(id))throw new ProcessingException("REQUIREMENT_ID_DUPLICATE");var matches=links.Where(l=>S(l,"requirement")==id).ToArray();var valid=matches.Where(l=>paths.Contains(S(l,"artifact"))&&S(l,"node")!=""&&S(l,"rationale")!="").ToArray();var status=S(requirement,"status")=="excluded"&&S(requirement,"exclusion_reason")!=""?"intentionally_excluded":valid.Length>0&&valid.Length==matches.Length&&valid.All(l=>S(l,"coverage")=="full")?"fully_modelled":valid.Length>0?"partially_modelled":"unresolved";counts[status]=counts[status]!.GetValue<int>()+1;rows.Add(new JsonObject{["requirement"]=id,["status"]=status,["links"]=new JsonArray(valid.Select(l=>(JsonNode)l.DeepClone()).ToArray()),["invalid_links"]=matches.Length-valid.Length});}var denominator=requirements.Count-counts["intentionally_excluded"]!.GetValue<int>();return new JsonObject{["counts"]=counts,["total"]=requirements.Count,["coverage_percent"]=denominator>0?JsonValue.Create(Math.Round(100m*counts["fully_modelled"]!.GetValue<int>()/denominator,2)):null,["requirements"]=rows,["basis"]="Explicit modeller assertions with existing artefact references; clinical semantics and execution not verified."};}
}
